-- custom UI background
getgenv().__PANDA_BG = function(fallback)
	if getgenv().__PANDA_BG_CACHED then return getgenv().__PANDA_BG_CACHED end
	local ok, result = pcall(function()
		local asset = getcustomasset or getsynasset
		if not (asset and isfile and writefile and readfile) then return nil end
		if isfolder and makefolder and not isfolder("PandaV1_Media_v2") then makefolder("PandaV1_Media_v2") end
		local path = "PandaV1_Media_v2/custom_bg.jpg"
		local have = false
		if isfile(path) then
			local okr, data = pcall(readfile, path)
			have = okr and data and #data > 1000
		end
		if not have then
			local data = game:HttpGet("https://i.pinimg.com/1200x/92/a3/c3/92a3c371a6ee74580ca74fecf7ffa531.jpg")
			if data and #data > 1000 then writefile(path, data) have = true end
		end
		if have then return asset(path) end
		return nil
	end)
	if ok and result then
		getgenv().__PANDA_BG_CACHED = result
		return result
	end
	return fallback
end


