getgenv().__PANDA_B64 = function(data)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local lut = {}
	for i = 1, 64 do lut[string.byte(chars, i)] = i - 1 end
	data = string.gsub(data, "[^%w%+/]", "")
	local out, n = {}, 0
	local len = #data
	local i = 1
	while i <= len do
		local a, b, c, d = string.byte(data, i, i + 3)
		a, b, c, d = lut[a], lut[b], lut[c], lut[d]
		local v = a * 262144 + (b or 0) * 4096 + (c or 0) * 64 + (d or 0)
		local b1 = math.floor(v / 65536) % 256
		local b2 = math.floor(v / 256) % 256
		local b3 = v % 256
		n = n + 1
		if c == nil then
			out[n] = string.char(b1)
		elseif d == nil then
			out[n] = string.char(b1, b2)
		else
			out[n] = string.char(b1, b2, b3)
		end
		i = i + 4
	end
	return table.concat(out)
end
getgenv().__PANDA_TAG_FRAMES = function(key)
	getgenv().__PANDA_TAG_CACHE = getgenv().__PANDA_TAG_CACHE or {}
	if getgenv().__PANDA_TAG_CACHE[key] then return getgenv().__PANDA_TAG_CACHE[key] end
	local ids = {}
	local ok = pcall(function()
		local asset = getcustomasset or getsynasset
		if not (asset and isfile and writefile) then error("no fs") end
		if isfolder and makefolder and not isfolder("PandaV1_Media_v2") then makefolder("PandaV1_Media_v2") end
		local set = getgenv().__PANDA_TAG_DATA[key]
		for i, b64 in ipairs(set.frames) do
			local path = "PandaV1_Media_v2/tagframe_v1_" .. key .. "_" .. i .. ".jpg"
			if not isfile(path) then writefile(path, getgenv().__PANDA_B64(b64)) end
			ids[#ids + 1] = asset(path)
		end
	end)
	if not ok or #ids == 0 then return nil end
	getgenv().__PANDA_TAG_CACHE[key] = ids
	pcall(function()
		task.spawn(function()
			game:GetService("ContentProvider"):PreloadAsync(ids)
		end)
	end)
	return ids
end
getgenv().__PANDA_PLAY_TAG = function(label, key)
	local ids = getgenv().__PANDA_TAG_FRAMES(key)
	if not ids then return false end
	local delay = getgenv().__PANDA_TAG_DATA[key].delay
	label.ImageTransparency = 0
	label.ImageColor3 = Color3.fromRGB(255, 255, 255)
	label.Image = ids[1]
	task.spawn(function()
		local i = 1
		while label and label.Parent do
			label.Image = ids[i]
			i = i % #ids + 1
			task.wait(delay)
		end
	end)
	return true
end

