getgenv().__PANDA_RAINBOW = function(label, speed)
	task.spawn(function()
		local hue = 0
		while label and label.Parent do
			hue = (hue + (speed or 0.012)) % 1
			label.TextColor3 = Color3.fromHSV(hue, 0.85, 1)
			task.wait(0.03)
		end
	end)
end

