--[[
    mortal Style Kidnape Sub-System & Standalone GUI
    Features:
    1. Merry-Go-Round Kidnap:
       - Requires player to sit in Merry-Go-Round (error if not sitting)
       - Teleports character & merry-go-round to target (replicates across server & target!)
       - Spins around target with seat proximity & firetouchinterest to force target into seat
       - Transports back to original position with target
    2. ⚡ Death Trap (Centrifugal Fling Out of Map):
       - Merry-Go-Round spins at lethal hyper-speed (400-2000 rad/s)
       - Locked strictly in ONE PLACE: zero linear velocity, pinned center CFrame, CanCollide off (no drifting!)
       - Detects if target/occupant jumps (Humanoid.Sit == false or unseats)
       - Instantly flings them into the void / out of map boundaries at hypersonic velocity!
       - Works during active kidnap or passively when sitting in the Merry-Go-Round
    3. Physics Rocket Kidnap:
       - 25 rad/s angular velocity spin for 3 seconds
       - Upward impulse launch (mass * 500)
    4. mortal Dark Premium UI Theme
--]]

local Players = game:GetService("Players")
local localPlayer_ = Players.LocalPlayer

local kidnapSettings = {
	mode = "MerryGoRound", -- "MerryGoRound" or "PhysicsRocket"
	spinSpeed = 45,
	spinRadius = 3.5,
	maxSpinWait = 25,
	rocketSpinSpeed = 25,
	rocketDuration = 3,
	rocketImpulse = 500,
	lockToTarget = true,
	loopKidnap = false,
	deathTrap = false,           -- Death Trap toggle
	deathTrapSpeed = 800,        -- Merry-Go-Round lethal spin speed (rad/s)
	deathTrapFlingForce = 20000, -- Catapult ejection speed out of map (studs/s)
	deathTrapMethod2 = false,    -- Death Trap Method 2 toggle (Walk Fling)
	active = false,
	targetPlayer = nil,
	statusText = "Idle",
}
_G.KidnapSettings = kidnapSettings

-- Notification helper
local function notify(title, msg, duration)
	if typeof(SendNotification) == "function" then
		pcall(function() SendNotification(title, msg, duration or 3) end)
	end
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", {
			Title = title,
			Text = msg,
			Duration = duration or 3,
		})
	end)
end

-- Target character resolution
local function getTargetPlayer()
	if kidnapSettings.targetPlayer and kidnapSettings.targetPlayer.Parent then
		return kidnapSettings.targetPlayer
	end
	if TargetPlayer and TargetPlayer.Parent then
		return TargetPlayer
	end
	return nil
end

local function getTargetCharacter()
	local p = getTargetPlayer()
	return p and p.Character
end

-- =========================================================================
-- DEATH TRAP CATAPULT (FLING OUT OF MAP)
-- =========================================================================
local function flingTargetOutOfMap(targetChar, targetRoot, assemblyPart)
	if not (targetRoot and targetRoot.Parent) then return end

	local myChar = localPlayer_ and localPlayer_.Character
	local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
	if targetRoot == myRoot then return end -- Protect kidnapper

	-- Outward radial trajectory + upward ballistic arc
	local centerPos = (assemblyPart and assemblyPart.Position) or targetRoot.Position
	local radial = targetRoot.Position - centerPos
	local horiz = Vector3.new(radial.X, 0, radial.Z)
	local dir
	if horiz.Magnitude > 0.1 then
		dir = (horiz.Unit + Vector3.new(0, 0.45, 0)).Unit
	elseif assemblyPart then
		dir = (assemblyPart.CFrame.LookVector + Vector3.new(0, 0.45, 0)).Unit
	else
		dir = Vector3.new(0, 1, 0)
	end

	local flingSpeed = kidnapSettings.deathTrapFlingForce or 20000
	local launchVelocity = dir * flingSpeed

	-- Ragdoll / trip humanoid so they cannot recover mid-air
	local hum = targetChar and targetChar:FindFirstChildOfClass("Humanoid")
	if hum then
		pcall(function()
			hum.PlatformStand = true
			hum.Sit = false
		end)
	end

	-- Apply multi-frame hypersonic impulse & linear velocity
	task.spawn(function()
		for i = 1, 20 do
			if not (targetRoot and targetRoot.Parent) then break end
			pcall(function()
				targetRoot.AssemblyLinearVelocity = launchVelocity
				targetRoot.AssemblyAngularVelocity = Vector3.new(
					math.random(-1500, 1500),
					math.random(2000, 4000),
					math.random(-1500, 1500)
				)
				targetRoot:ApplyImpulse(launchVelocity * (targetRoot.AssemblyMass or 50))
				if targetChar then
					for _, part in ipairs(targetChar:GetChildren()) do
						if part:IsA("BasePart") then
							part.AssemblyLinearVelocity = launchVelocity
						end
					end
				end
			end)
			game:GetService("RunService").Heartbeat:Wait()
		end
	end)
end

-- Background passive death trap for any player jumping from Merry-Go-Round
-- Locked in ONE PLACE: stays strictly at fixedPosition with zero linear velocity
local passiveTrapRunning = false
local function updatePassiveDeathTrap()
	if kidnapSettings.deathTrap and not kidnapSettings.active then
		if passiveTrapRunning then return end
		passiveTrapRunning = true

		task.spawn(function()
			notify("⚡ Death Trap", "Death Trap active! Spinning in place; any player who jumps will be flung out of the map!", 3)

			local seatOccupantMap = {}
			local fixedCenterPos = nil

			while kidnapSettings.deathTrap and not kidnapSettings.active do
				local myChar = localPlayer_ and localPlayer_.Character
				local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
				local currentSeat = myHum and myHum.SeatPart

				if myHum and myHum.Sit and currentSeat then
					local merryModel = currentSeat:FindFirstAncestorOfClass("Model") or currentSeat.Parent
					local assemblyPart = currentSeat.AssemblyRootPart or currentSeat
					local trapSpeed = kidnapSettings.deathTrapSpeed or 800

					-- Find fixed center pivot position once so it NEVER moves across the map
					if not fixedCenterPos then
						if merryModel then
							for _, p in ipairs(merryModel:GetDescendants()) do
								if p:IsA("BasePart") and p.Anchored then
									fixedCenterPos = p.Position + Vector3.new(0, 1.2, 0)
									break
								end
							end
						end
						if not fixedCenterPos then
							fixedCenterPos = assemblyPart.Position
						end
					end

					-- Disable collisions on merry parts to eliminate ground friction/bouncing
					if merryModel then
						for _, p in ipairs(merryModel:GetDescendants()) do
							if p:IsA("BasePart") and p.CanCollide then
								pcall(function() p.CanCollide = false end)
							end
						end
					end

					-- Lock in ONE place: pin position strictly to fixedCenterPos, zero linear velocity, pure Y-axis spin
					pcall(function()
						local curRot = assemblyPart.CFrame - assemblyPart.CFrame.Position
						assemblyPart.CFrame = CFrame.new(fixedCenterPos) * curRot
						assemblyPart.AssemblyLinearVelocity = Vector3.zero
						assemblyPart.AssemblyAngularVelocity = Vector3.new(0, trapSpeed, 0)
					end)

					local seats = {}
					if merryModel then
						for _, desc in ipairs(merryModel:GetDescendants()) do
							if (desc:IsA("Seat") or desc:IsA("VehicleSeat")) and desc ~= currentSeat then
								table.insert(seats, desc)
							end
						end
					end

					for _, s in ipairs(seats) do
						local occ = s.Occupant
						if occ and occ:IsA("Humanoid") and occ ~= myHum then
							local char = occ.Parent
							local root = char and char:FindFirstChild("HumanoidRootPart")
							local p = Players:GetPlayerFromCharacter(char)
							seatOccupantMap[s] = {
								humanoid = occ,
								char = char,
								root = root,
								player = p,
								name = p and p.DisplayName or (char and char.Name or "Player"),
							}
						elseif not occ and seatOccupantMap[s] then
							local victim = seatOccupantMap[s]
							seatOccupantMap[s] = nil
							if victim.root and victim.root.Parent then
								notify("⚡ Death Trap Triggered!", victim.name .. " jumped and was flung out of the map!", 4)
								flingTargetOutOfMap(victim.char, victim.root, assemblyPart)
							end
						end
					end
				else
					seatOccupantMap = {}
					fixedCenterPos = nil
				end
				task.wait(0.04)
			end

			local myChar = localPlayer_ and localPlayer_.Character
			local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
			local currentSeat = myHum and myHum.SeatPart
			if currentSeat then
				local assemblyPart = currentSeat.AssemblyRootPart or currentSeat
				pcall(function()
					assemblyPart.AssemblyAngularVelocity = Vector3.zero
					assemblyPart.AssemblyLinearVelocity = Vector3.zero
				end)
			end

			passiveTrapRunning = false
		end)
	end
end
_G.UpdatePassiveDeathTrap = updatePassiveDeathTrap

-- =========================================================================
-- ⚡ DEATH TRAP METHOD 2: PHYSICS WALK FLING (STATE 11 + HYPERSONIC VELOCITY)
-- =========================================================================
local walkflinging = false
local walkFlingDiedConn = nil
local walkFlingJumpConn = nil

local function setDeathTrapMethod2(enable)
	if enable then
		if walkflinging then return end
		walkflinging = true
		kidnapSettings.deathTrapMethod2 = true
		if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = true end

		task.spawn(function()
			local Players = game:GetService("Players")
			local RunService = game:GetService("RunService")
			local UserInputService = game:GetService("UserInputService")
			local LocalPlayer = Players.LocalPlayer

			local Character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
			local Root = Character:WaitForChild("HumanoidRootPart", 5)
			local Humanoid = Character:WaitForChild("Humanoid", 5)

			if not Root or not Humanoid then
				walkflinging = false
				kidnapSettings.deathTrapMethod2 = false
				if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
				notify("Death Trap M2", "Character or HumanoidRootPart not found!", 2)
				if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
				return
			end

			notify("⚡ Death Trap Method 2", "Walk Fling active! Walk or jump into any player to fling them.", 3)

			if walkFlingDiedConn then pcall(function() walkFlingDiedConn:Disconnect() end) end
			walkFlingDiedConn = Humanoid.Died:Connect(function()
				walkflinging = false
				kidnapSettings.deathTrapMethod2 = false
				if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
				if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
			end)

			-- Add jump ability
			if walkFlingJumpConn then pcall(function() walkFlingJumpConn:Disconnect() end) end
			walkFlingJumpConn = UserInputService.JumpRequest:Connect(function()
				if Humanoid and Humanoid.Parent then
					pcall(function() Humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end)
				end
			end)

			pcall(function()
				Root.CanCollide = false
				Humanoid:ChangeState(11)
			end)

			repeat 
				RunService.Heartbeat:Wait()
				if not walkflinging then break end
				local vel = Root.Velocity
				Root.Velocity = vel * 10000 + Vector3.new(0, 10000, 0)
				RunService.RenderStepped:Wait()
				if not walkflinging then break end
				Root.Velocity = vel
				RunService.Stepped:Wait()
				if not walkflinging then break end
				Root.Velocity = vel + Vector3.new(0, 0.1, 0)
			until walkflinging == false

			pcall(function()
				if Root and Root.Parent then
					Root.Velocity = Vector3.new(0, 0, 0)
					Root.CanCollide = true
				end
				if Humanoid and Humanoid.Parent and Humanoid.Health > 0 then
					Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
				end
			end)

			if walkFlingDiedConn then pcall(function() walkFlingDiedConn:Disconnect() end) walkFlingDiedConn = nil end
			if walkFlingJumpConn then pcall(function() walkFlingJumpConn:Disconnect() end) walkFlingJumpConn = nil end
			walkflinging = false
			kidnapSettings.deathTrapMethod2 = false
			if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
			if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
		end)
	else
		walkflinging = false
		kidnapSettings.deathTrapMethod2 = false
		if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
		if walkFlingDiedConn then pcall(function() walkFlingDiedConn:Disconnect() end) walkFlingDiedConn = nil end
		if walkFlingJumpConn then pcall(function() walkFlingJumpConn:Disconnect() end) walkFlingJumpConn = nil end
		local Character = localPlayer_ and localPlayer_.Character
		local Root = Character and Character:FindFirstChild("HumanoidRootPart")
		local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
		pcall(function()
			if Root then
				Root.Velocity = Vector3.new(0, 0, 0)
				Root.CanCollide = true
			end
			if Humanoid and Humanoid.Health > 0 then
				Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
			end
		end)
		notify("Death Trap M2", "Death Trap Method 2 (Walk Fling) disabled.", 2)
		if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
	end
end
_G.SetDeathTrapMethod2 = setDeathTrapMethod2
_G.ToggleDeathTrapMethod2 = function()
	setDeathTrapMethod2(not kidnapSettings.deathTrapMethod2)
end


-- =========================================================================
-- 1. MERRY-GO-ROUND KIDNAP MECHANIC (REPLICATED TO TARGET + PINNED IN PLACE)
-- =========================================================================
local function startMerryGoRoundKidnap()
	local myChar = localPlayer_ and localPlayer_.Character
	local myHumanoid = myChar and myChar:FindFirstChildOfClass("Humanoid")
	local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")

	-- 1. CHECK IF LOCAL PLAYER IS SITTING
	local currentSeat = myHumanoid and myHumanoid.SeatPart
	if not (myHumanoid and myHumanoid.Sit and currentSeat) then
		kidnapSettings.statusText = "Error: Player is not sitting!"
		notify("Kidnape Error", "Player is not sitting! Please sit in the Merry-Go-Round first.", 4)
		return
	end

	-- 2. RESOLVE MERRY-GO-ROUND MODEL & ORIGINAL POSITION
	local merryModel = currentSeat:FindFirstAncestorOfClass("Model") or currentSeat.Parent
	local assemblyPart = currentSeat.AssemblyRootPart or currentSeat

	-- Pinpoint fixed anchor center
	local fixedCenterPos = nil
	if merryModel then
		for _, p in ipairs(merryModel:GetDescendants()) do
			if p:IsA("BasePart") and p.Anchored then
				fixedCenterPos = p.Position + Vector3.new(0, 1.2, 0)
				break
			end
		end
	end
	if not fixedCenterPos then
		fixedCenterPos = assemblyPart.Position
	end

	local originalCFrame = nil
	if merryModel and merryModel:IsA("Model") and merryModel.PrimaryPart then
		originalCFrame = merryModel.PrimaryPart.CFrame
	elseif merryModel and merryModel:IsA("Model") then
		originalCFrame = merryModel:GetPivot()
	else
		originalCFrame = currentSeat.CFrame
	end

	local originalAssemblyCFrame = assemblyPart.CFrame
	local originalMyRootCFrame = myRoot and myRoot.CFrame or originalAssemblyCFrame

	-- Gather all seats on the merry-go-round
	local allSeats = {}
	if merryModel then
		for _, desc in ipairs(merryModel:GetDescendants()) do
			if desc:IsA("Seat") or desc:IsA("VehicleSeat") then
				table.insert(allSeats, desc)
			end
		end
	end
	if #allSeats == 0 then
		table.insert(allSeats, currentSeat)
	end

	-- 3. RESOLVE TARGET PLAYER
	local targetP = getTargetPlayer()
	local targetChar = targetP and targetP.Character
	local targetHumanoid = targetChar and targetChar:FindFirstChildOfClass("Humanoid")
	local targetRoot = targetChar and targetChar:FindFirstChild("HumanoidRootPart")

	if not (targetP and targetChar and targetHumanoid and targetRoot) then
		kidnapSettings.statusText = "Error: No target player selected!"
		notify("Kidnape Error", "No target player selected! Select a target first.", 3)
		return
	end

	kidnapSettings.active = true
	local targetDisplayName = targetP.DisplayName or targetP.Name
	kidnapSettings.statusText = "Flying to " .. targetDisplayName .. " with Merry-Go-Round..."
	notify("Kidnape", "Flying to " .. targetDisplayName .. "!", 3)

	-- Disable collision on merry parts for smooth travel
	for _, p in ipairs(merryModel:GetDescendants()) do
		if p:IsA("BasePart") then
			pcall(function() p.CanCollide = false end)
		end
	end

	-- 4. TRANSPORT TO TARGET (MOVE BOTH MYROOT AND ASSEMBLY SO TARGET SEES IT!)
	local travelPos = targetRoot.Position + Vector3.new(0, 1.5, 0)
	pcall(function()
		-- Moving myRoot ensures client-to-server replication so target ACTUALLY sees you!
		if myRoot then
			myRoot.CFrame = CFrame.new(travelPos)
			myRoot.AssemblyLinearVelocity = Vector3.zero
		end
		assemblyPart.CFrame = CFrame.new(travelPos)
		assemblyPart.AssemblyLinearVelocity = Vector3.zero
		assemblyPart.AssemblyAngularVelocity = Vector3.zero
	end)
	task.wait(0.2)

	-- 5. SPIN AROUND TARGET UNTIL THEY SIT (OR CAPTURE TIMEOUT)
	kidnapSettings.statusText = "Spinning around " .. targetDisplayName .. "... Forcing into seat!"
	local spinRadius = kidnapSettings.spinRadius or 3.5
	local spinAngle = 0
	local spinSpeed = kidnapSettings.spinSpeed or 45
	local timeout = tick() + (kidnapSettings.maxSpinWait or 25)

	while kidnapSettings.active and tick() < timeout do
		if not targetChar or not targetChar.Parent or not targetHumanoid or not targetRoot or not targetRoot.Parent then
			break
		end

		-- Check if target has sat down
		local targetSat = false
		if targetHumanoid.Sit == true then
			targetSat = true
		end
		for _, s in ipairs(allSeats) do
			if s ~= currentSeat and s.Occupant and s.Occupant.Parent == targetChar then
				targetSat = true
				break
			end
		end

		if targetSat then
			kidnapSettings.statusText = "Target captured! Sitting in seat!"
			break
		end

		-- Spin around target (moving BOTH myRoot and assembly so it replicates to target!)
		spinAngle = spinAngle + math.rad(spinSpeed)
		local offset = Vector3.new(math.cos(spinAngle) * spinRadius, 0.5, math.sin(spinAngle) * spinRadius)
		local currentTargetPos = targetRoot.Position
		local lookCFrame = CFrame.new(currentTargetPos + offset, currentTargetPos)

		pcall(function()
			if myRoot then
				myRoot.CFrame = lookCFrame
				myRoot.AssemblyLinearVelocity = Vector3.zero
			end
			assemblyPart.CFrame = lookCFrame
			assemblyPart.AssemblyLinearVelocity = Vector3.new(0, 0.1, 0)
			assemblyPart.AssemblyAngularVelocity = Vector3.new(0, spinSpeed, 0)
		end)

		-- Push empty seats towards target and fire touch interest to force seat prompt / sit
		for _, s in ipairs(allSeats) do
			if s ~= currentSeat and not s.Occupant then
				pcall(function()
					s.CFrame = targetRoot.CFrame * CFrame.new(0, 0, 0.2)
					if type(firetouchinterest) == "function" and targetRoot then
						firetouchinterest(s, targetRoot, 0)
						task.wait()
						firetouchinterest(s, targetRoot, 1)
					end
				end)
			end
		end

		task.wait(0.03)
	end

	-- 6. RETURN TO ORIGINAL MERRY-GO-ROUND POSITION
	if kidnapSettings.active and (originalAssemblyCFrame or originalCFrame) then
		kidnapSettings.statusText = "Returning to original position..."
		task.wait(0.2) -- allow seat weld to stabilize

		pcall(function()
			if myRoot and originalMyRootCFrame then
				myRoot.CFrame = originalMyRootCFrame
				myRoot.AssemblyLinearVelocity = Vector3.zero
			end
			if originalAssemblyCFrame then
				assemblyPart.CFrame = originalAssemblyCFrame
			elseif originalCFrame then
				assemblyPart.CFrame = originalCFrame
			end
			assemblyPart.AssemblyLinearVelocity = Vector3.zero
			assemblyPart.AssemblyAngularVelocity = Vector3.zero

			if merryModel and merryModel:IsA("Model") and originalCFrame then
				if merryModel.PrimaryPart then
					merryModel:SetPrimaryPartCFrame(originalCFrame)
				else
					merryModel:PivotTo(originalCFrame)
				end
			end
		end)

		notify("Kidnape Success", targetDisplayName .. " abducted & brought to Merry-Go-Round!", 4)
		kidnapSettings.statusText = "Kidnap Complete! Target abducted."

		-- 7. DEATH TRAP (HYPER-SPIN IN ONE PLACE & CATAPULT OUT OF MAP)
		if kidnapSettings.active and kidnapSettings.deathTrap then
			kidnapSettings.statusText = "⚡ DEATH TRAP ACTIVE: Spinning in place at " .. tostring(kidnapSettings.deathTrapSpeed or 800) .. " rad/s!"
			notify("⚡ Death Trap Engaged", "Target trapped in hyper-spin! If they jump, they will be thrown out of the map!", 4)

			local trapSpeed = kidnapSettings.deathTrapSpeed or 800
			local flingTriggered = false
			local deathTrapConn = nil
			local trapTimeout = tick() + 60 -- max 60 seconds

			-- Disable collision so it NEVER collides with ground/obstacles
			for _, p in ipairs(merryModel:GetDescendants()) do
				if p:IsA("BasePart") then
					pcall(function() p.CanCollide = false end)
				end
			end

			deathTrapConn = game:GetService("RunService").Heartbeat:Connect(function()
				if not kidnapSettings.active or not kidnapSettings.deathTrap or flingTriggered or tick() > trapTimeout then
					if deathTrapConn then deathTrapConn:Disconnect() deathTrapConn = nil end
					return
				end

				-- PINNED IN ONE PLACE: Keep position locked to fixedCenterPos, linear velocity strictly zero
				pcall(function()
					local curRot = assemblyPart.CFrame - assemblyPart.CFrame.Position
					assemblyPart.CFrame = CFrame.new(fixedCenterPos) * curRot
					assemblyPart.AssemblyLinearVelocity = Vector3.zero
					assemblyPart.AssemblyAngularVelocity = Vector3.new(0, trapSpeed, 0)
				end)

				-- Check if target jumped or left seat
				local targetStillSitting = false
				if targetHumanoid and targetHumanoid.Parent and targetHumanoid.Sit == true then
					for _, s in ipairs(allSeats) do
						if s ~= currentSeat and s.Occupant == targetHumanoid then
							targetStillSitting = true
							break
						end
					end
				end

				if not targetStillSitting and not flingTriggered then
					flingTriggered = true
					if deathTrapConn then deathTrapConn:Disconnect() deathTrapConn = nil end

					kidnapSettings.statusText = "💀 Target jumped! FLUNG OUT OF MAP!"
					notify("⚡ Death Trap Triggered!", targetDisplayName .. " jumped and was catapulted out of the map!", 4)

					flingTargetOutOfMap(targetChar, targetRoot, assemblyPart)

					task.spawn(function()
						task.wait(1.5)
						pcall(function()
							assemblyPart.AssemblyAngularVelocity = Vector3.zero
							assemblyPart.AssemblyLinearVelocity = Vector3.zero
						end)
					end)
				end
			end)

			while kidnapSettings.active and kidnapSettings.deathTrap and not flingTriggered and tick() < trapTimeout do
				task.wait(0.1)
			end

			if deathTrapConn then pcall(function() deathTrapConn:Disconnect() end) end
		end
	else
		kidnapSettings.statusText = "Kidnap Stopped / Timed Out."
	end

	task.wait(1.5)
	kidnapSettings.active = false
	kidnapSettings.statusText = "Idle"
end

-- =========================================================================
-- 2. PHYSICS ROCKET SPIN & LAUNCH MECHANIC
-- =========================================================================
local function startPhysicsRocketKidnap()
	local targetP = getTargetPlayer()
	local targetChar = targetP and targetP.Character or (localPlayer_ and localPlayer_.Character)
	if not targetChar then
		notify("Kidnape Error", "No character found for rocket kidnap!", 3)
		return
	end

	local targetRoot = targetChar:FindFirstChild("HumanoidRootPart")
	if not targetRoot then return end

	kidnapSettings.active = true
	local targetName = targetChar.Name
	kidnapSettings.statusText = "Rocket Kidnapping " .. targetName .. "..."

	local myChar = localPlayer_ and localPlayer_.Character
	local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")

	-- Optional lock to target
	local attachConn = nil
	if kidnapSettings.lockToTarget and myRoot and targetRoot ~= myRoot then
		attachConn = game:GetService("RunService").Heartbeat:Connect(function()
			if not kidnapSettings.active or not myRoot or not myRoot.Parent or not targetRoot or not targetRoot.Parent then
				if attachConn then attachConn:Disconnect() end
				return
			end
			pcall(function()
				myRoot.CFrame = targetRoot.CFrame * CFrame.new(0, 0, 1.2)
				myRoot.AssemblyLinearVelocity = Vector3.zero
			end)
		end)
	end

	-- Attachment and AngularVelocity spin (exact user source code)
	local attachment = Instance.new("Attachment")
	attachment.Name = "KidnapAttachment"
	attachment.Parent = targetRoot

	local spin = Instance.new("AngularVelocity")
	spin.Name = "KidnapSpin"
	spin.Attachment0 = attachment
	spin.MaxTorque = math.huge
	spin.AngularVelocity = Vector3.new(0, kidnapSettings.rocketSpinSpeed or 25, 0)
	spin.Parent = targetRoot

	local mySpin, myAttachment = nil, nil
	if myRoot and myRoot ~= targetRoot then
		myAttachment = Instance.new("Attachment")
		myAttachment.Name = "KidnapMyAttachment"
		myAttachment.Parent = myRoot

		mySpin = Instance.new("AngularVelocity")
		mySpin.Name = "KidnapMySpin"
		mySpin.Attachment0 = myAttachment
		mySpin.MaxTorque = math.huge
		mySpin.AngularVelocity = Vector3.new(0, kidnapSettings.rocketSpinSpeed or 25, 0)
		mySpin.Parent = myRoot
	end

	local duration = kidnapSettings.rocketDuration or 3
	local startTime = tick()
	while kidnapSettings.active and (tick() - startTime) < duration do
		task.wait(0.1)
	end

	if attachConn then pcall(function() attachConn:Disconnect() end) end
	if spin and spin.Parent then pcall(function() spin:Destroy() end) end
	if attachment and attachment.Parent then pcall(function() attachment:Destroy() end) end
	if mySpin and mySpin.Parent then pcall(function() mySpin:Destroy() end) end
	if myAttachment and myAttachment.Parent then pcall(function() myAttachment:Destroy() end) end

	-- Rocket launch impulse (exact user source code)
	if kidnapSettings.active then
		kidnapSettings.statusText = "Blasted into Stratosphere!"
		local impulseMult = kidnapSettings.rocketImpulse or 500
		if targetRoot and targetRoot.Parent then
			pcall(function()
				targetRoot:ApplyImpulse(Vector3.new(0, 1, 0) * targetRoot.AssemblyMass * impulseMult)
			end)
		end
		if myRoot and myRoot.Parent and myRoot ~= targetRoot then
			pcall(function()
				myRoot:ApplyImpulse(Vector3.new(0, 1, 0) * myRoot.AssemblyMass * impulseMult)
			end)
		end
		notify("Rocket Launch", "Target propelled into outer space!", 3)
	end

	task.wait(1)
	kidnapSettings.active = false
	kidnapSettings.statusText = "Idle"
end

_G.StartKidnapTarget = function()
	task.spawn(function()
		if kidnapSettings.mode == "MerryGoRound" then
			startMerryGoRoundKidnap()
		else
			startPhysicsRocketKidnap()
		end
	end)
end

_G.StopKidnapTarget = function()
	kidnapSettings.active = false
	kidnapSettings.loopKidnap = false
	kidnapSettings.statusText = "Cancelled"
	local myChar = localPlayer_ and localPlayer_.Character
	local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
	local currentSeat = myHum and myHum.SeatPart
	if currentSeat then
		local assemblyPart = currentSeat.AssemblyRootPart or currentSeat
		pcall(function()
			assemblyPart.AssemblyAngularVelocity = Vector3.zero
			assemblyPart.AssemblyLinearVelocity = Vector3.zero
		end)
	end
	if myChar then
		for _, v in ipairs(myChar:GetDescendants()) do
			if v.Name:find("Kidnap") then
				pcall(function() v:Destroy() end)
			end
		end
	end
	notify("Kidnape", "Kidnap operations stopped.", 2)
end

-- =========================================================================
-- 3. mortal THEMED STANDALONE "KIDNAPE" GUI
-- =========================================================================
_G.LaunchKidnapeGUI = function()
	local hui
	if gethui then
		hui = gethui() or game:GetService("CoreGui")
	else
		hui = game:GetService("CoreGui")
	end
	hui = hui or (localPlayer_ and localPlayer_:WaitForChild("PlayerGui"))

	if hui:FindFirstChild("KidnapeGUI") then
		hui.KidnapeGUI:Destroy()
	end

	local screenGui = Instance.new("ScreenGui")
	screenGui.Name = "KidnapeGUI"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	screenGui.Parent = hui

	-- mortal Theme Colors
	local cBg = Color3.fromRGB(15, 15, 22)
	local cCard = Color3.fromRGB(22, 22, 32)
	local cCardHover = Color3.fromRGB(28, 28, 42)
	local cAccent = _themeColor or Color3.fromRGB(145, 65, 245)
	local cAccentDark = Color3.fromRGB(100, 45, 180)
	local cText = Color3.fromRGB(245, 245, 255)
	local cTextMuted = Color3.fromRGB(155, 155, 185)
	local cSuccess = Color3.fromRGB(45, 205, 115)
	local cDanger = Color3.fromRGB(240, 65, 85)

	-- Window Frame
	local mainFrame = Instance.new("Frame")
	mainFrame.Name = "MainFrame"
	mainFrame.Size = UDim2.new(0, 340, 0, 520)
	mainFrame.Position = UDim2.new(0.5, -170, 0.5, -260)
	mainFrame.BackgroundColor3 = cBg
	mainFrame.BorderSizePixel = 0
	mainFrame.ClipsDescendants = true
	mainFrame.Parent = screenGui

	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 12)
	corner.Parent = mainFrame

	local stroke = Instance.new("UIStroke")
	stroke.Color = cAccent
	stroke.Thickness = 1.4
	stroke.Transparency = 0.3
	stroke.Parent = mainFrame

	local strokeGrad = Instance.new("UIGradient")
	strokeGrad.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0, cAccent),
		ColorSequenceKeypoint.new(0.5, Color3.fromRGB(220, 120, 255)),
		ColorSequenceKeypoint.new(1, cAccent),
	})
	strokeGrad.Rotation = 45
	strokeGrad.Parent = stroke

	-- Draggable TitleBar
	local titleBar = Instance.new("Frame")
	titleBar.Name = "TitleBar"
	titleBar.Size = UDim2.new(1, 0, 0, 42)
	titleBar.BackgroundColor3 = cCard
	titleBar.BorderSizePixel = 0
	titleBar.Parent = mainFrame

	local tbCorner = Instance.new("UICorner")
	tbCorner.CornerRadius = UDim.new(0, 12)
	tbCorner.Parent = titleBar

	local titleLabel = Instance.new("TextLabel")
	titleLabel.Size = UDim2.new(0, 100, 1, 0)
	titleLabel.Position = UDim2.new(0, 14, 0, 0)
	titleLabel.BackgroundTransparency = 1
	titleLabel.Text = "KIDNAPE"
	titleLabel.TextColor3 = cText
	titleLabel.Font = Enum.Font.GothamBold
	titleLabel.TextSize = 15
	titleLabel.TextXAlignment = Enum.TextXAlignment.Left
	titleLabel.Parent = titleBar

	local badge = Instance.new("TextLabel")
	badge.Size = UDim2.new(0, 75, 0, 20)
	badge.Position = UDim2.new(0, 92, 0.5, -10)
	badge.BackgroundColor3 = cAccentDark
	badge.Text = "mortal"
	badge.TextColor3 = Color3.fromRGB(255, 255, 255)
	badge.Font = Enum.Font.GothamBold
	badge.TextSize = 10
	badge.Parent = titleBar
	local bCorner = Instance.new("UICorner")
	bCorner.CornerRadius = UDim.new(0, 5)
	bCorner.Parent = badge

	local closeBtn = Instance.new("TextButton")
	closeBtn.Size = UDim2.new(0, 28, 0, 28)
	closeBtn.Position = UDim2.new(1, -34, 0.5, -14)
	closeBtn.BackgroundColor3 = Color3.fromRGB(38, 22, 28)
	closeBtn.Text = "X"
	closeBtn.TextColor3 = cDanger
	closeBtn.Font = Enum.Font.GothamBold
	closeBtn.TextSize = 13
	closeBtn.Parent = titleBar
	local cBtnCorner = Instance.new("UICorner")
	cBtnCorner.CornerRadius = UDim.new(0, 6)
	cBtnCorner.Parent = closeBtn
	closeBtn.MouseButton1Click:Connect(function()
		screenGui:Destroy()
	end)

	local minBtn = Instance.new("TextButton")
	minBtn.Size = UDim2.new(0, 28, 0, 28)
	minBtn.Position = UDim2.new(1, -66, 0.5, -14)
	minBtn.BackgroundColor3 = Color3.fromRGB(28, 28, 38)
	minBtn.Text = "-"
	minBtn.TextColor3 = cTextMuted
	minBtn.Font = Enum.Font.GothamBold
	minBtn.TextSize = 16
	minBtn.Parent = titleBar
	local mBtnCorner = Instance.new("UICorner")
	mBtnCorner.CornerRadius = UDim.new(0, 6)
	mBtnCorner.Parent = minBtn

	local isMin = false
	minBtn.MouseButton1Click:Connect(function()
		isMin = not isMin
		if isMin then
			mainFrame:TweenSize(UDim2.new(0, 340, 0, 42), "Out", "Quad", 0.22, true)
		else
			mainFrame:TweenSize(UDim2.new(0, 340, 0, 520), "Out", "Quad", 0.22, true)
		end
	end)

	-- Smooth Dragging
	local dragging, dragInput, dragStart, startPos
	titleBar.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = mainFrame.Position
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)
	titleBar.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			dragInput = input
		end
	end)
	game:GetService("UserInputService").InputChanged:Connect(function(input)
		if input == dragInput and dragging then
			local delta = input.Position - dragStart
			mainFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
	end)

