	local function addCycleOption(name, currentVal, values, callback)
		local btn = Instance.new("TextButton")
		btn.Size = UDim2.new(1, 0, 0, 26)
		btn.BackgroundColor3 = Color3.fromRGB(18, 18, 26)
		btn.Text = name .. ": " .. tostring(currentVal)
		btn.TextColor3 = cTextMuted
		btn.Font = Enum.Font.GothamMedium
		btn.TextSize = 11
		btn.Parent = optionsCard
		local bC = Instance.new("UICorner")
		bC.CornerRadius = UDim.new(0, 6)
		bC.Parent = btn

		local idx = 1
		for i, v in ipairs(values) do
			if v == currentVal then idx = i break end
		end

		btn.MouseButton1Click:Connect(function()
			idx = (idx % #values) + 1
			local chosen = values[idx]
			btn.Text = name .. ": " .. tostring(chosen)
			callback(chosen)
		end)
	end

