		        SkyboxUp             = existingSky.SkyboxUp,
		        CelestialBodiesShown = existingSky.CelestialBodiesShown,
		        StarCount            = existingSky.StarCount,
		    }
		end
		
		local existingAtmo = Lighting:FindFirstChildOfClass("Atmosphere")
		if existingAtmo then
		    getgenv().ORIGINAL_ATMO = {
		        Density = existingAtmo.Density,
		        Offset  = existingAtmo.Offset,
		        Color   = existingAtmo.Color,
		        Decay   = existingAtmo.Decay,
		        Glare   = existingAtmo.Glare,
		        Haze    = existingAtmo.Haze,
		    }
		end
		
		-- ------------------------------------------------
		-- Snapshot Terrain water
		-- ------------------------------------------------
		local Terrain = Workspace:FindFirstChildOfClass("Terrain")
		if Terrain then
		    getgenv().ORIGINAL_WATER = {
		        WaterColor        = Terrain.WaterColor,
		        WaterReflectance  = Terrain.WaterReflectance,
		        WaterTransparency = Terrain.WaterTransparency,
		        WaterWaveSize     = Terrain.WaterWaveSize,
		        WaterWaveSpeed    = Terrain.WaterWaveSpeed,
		    }
		end
		
		print(string.format("[Snapshot] Ready. Saved %d part colors, lighting, sky, atmosphere & water. Safe to run shaders.", colorCount))
		
		-- ------------------------------------------------
		-- Apply Red Cosmos Colors
		-- ------------------------------------------------
		local function toRedTint(c)
		    local lum = 0.299 * c.R + 0.587 * c.G + 0.114 * c.B
		    -- A much softer, desaturated red/gray tint
		    return Color3.new(lum * 0.9, lum * 0.65, lum * 0.65)
		end
		
		local colorCache = {}
		
		local function applyTint(part)
		    if not part:IsA('BasePart') and not part:IsA('Terrain') then return end
		    if part.Name == "PandaTile" then return end
		    if colorCache[part] then return end
		    if isCharacterPart(part) then return end
		
		    colorCache[part] = true
		    
		    if part:IsA("Terrain") then
		        part.WaterColor = Color3.fromRGB(180, 20, 20)
		    else
		        part.Color = toRedTint(part.Color)
		    end
		end
		
		for _, obj in ipairs(workspace:GetDescendants()) do
		    pcall(applyTint, obj)
		end
		
		workspace.DescendantAdded:Connect(function(inst)
		    task.defer(function()
		        pcall(applyTint, inst)
		    end)
		end)
		
		local function protectAvatar(char)
		    if not char then return end
		
		    for _, part in ipairs(char:GetDescendants()) do
		        pcall(function()
		            if part:IsA('BasePart') and colorCache[part] then
		                colorCache[part] = nil
		            end
		        end)
		    end
		
		    char.DescendantAdded:Connect(function(inst)
		        task.defer(function()
		            pcall(function()
		                if inst:IsA('BasePart') then
		                    colorCache[inst] = nil
		                end
		            end)
		        end)
		    end)
		end
		
		for _, plr in ipairs(Players:GetPlayers()) do
		    protectAvatar(plr.Character)
		    plr.CharacterAdded:Connect(protectAvatar)
		end
		
		Players.PlayerAdded:Connect(function(plr)
		    protectAvatar(plr.Character)
		    plr.CharacterAdded:Connect(protectAvatar)
		end)
		
		-- ------------------------------------------------
		-- Apply Red Cosmos Lighting & Skybox
		-- ------------------------------------------------
		Lighting:ClearAllChildren()
		
		local sky = Instance.new('Sky')
		sky.SkyboxBk = 'http://www.roblox.com/asset/?id=15542476630'
		sky.SkyboxDn = 'http://www.roblox.com/asset/?id=15542477272'
		sky.SkyboxFt = 'http://www.roblox.com/asset/?id=15542481240'
		sky.SkyboxLf = 'http://www.roblox.com/asset/?id=15542482020'
		sky.SkyboxRt = 'http://www.roblox.com/asset/?id=15542483287'
		sky.SkyboxUp = 'http://www.roblox.com/asset/?id=15542484852'
		sky.StarCount = 3000
		sky.SunAngularSize = 21
		sky.SunTextureId = "rbxassetid://1084351190"
		sky.Parent = Lighting
		
		local atmo = Instance.new('Atmosphere')
		atmo.Density = 0.25
		atmo.Offset = 0.15
		atmo.Color = Color3.fromRGB(180, 80, 80)
		atmo.Decay = Color3.fromRGB(80, 30, 40)
		atmo.Glare = 0.05
		atmo.Haze = 0.05
		atmo.Parent = Lighting
		
		Lighting.Ambient = Color3.fromRGB(110, 80, 80)
		Lighting.OutdoorAmbient = Color3.fromRGB(130, 90, 90)
		Lighting.ColorShift_Top = Color3.fromRGB(255, 190, 190)
		Lighting.ColorShift_Bottom = Color3.fromRGB(80, 50, 50)
		Lighting.FogColor = Color3.fromRGB(30, 10, 15)
		Lighting.FogEnd = 999999
		Lighting.Brightness = 1.8
		Lighting.ExposureCompensation = 0
		Lighting.GlobalShadows = true
		Lighting.ClockTime = 12 -- 90-degree angle (directly overhead)
		Lighting.GeographicLatitude = 0
		Lighting.ShadowSoftness = 0.2
		Lighting.EnvironmentDiffuseScale = 1
		Lighting.EnvironmentSpecularScale = 1
		
		local bloom = Instance.new('BloomEffect')
		bloom.Enabled = true
		bloom.Intensity = 0.3
		bloom.Size = 42
		bloom.Threshold = 0.95
		bloom.Parent = Lighting
		
		local sunrays = Instance.new('SunRaysEffect')
		sunrays.Enabled = true
		sunrays.Intensity = 0.15
		sunrays.Spread = 0.8
		sunrays.Parent = Lighting
		
		local colorCorrection = Instance.new('ColorCorrectionEffect')
		colorCorrection.Saturation = 0.1
		colorCorrection.Brightness = 0.05
		colorCorrection.Contrast = 0.2
		colorCorrection.TintColor = Color3.fromRGB(255, 230, 230)
		colorCorrection.Enabled = true
		colorCorrection.Parent = Lighting
		
		print("[Red Cosmos] Shader successfully applied!")
	end,
	["reset.lua"] = function()
		-- ================================================
		--   STEP 2: FULL RESET (Glow + Fog Fix)
		-- ================================================
		
		local Players    = game:GetService("Players")
		local Lighting   = game:GetService("Lighting")
		local Workspace  = game:GetService("Workspace")
		local RunService = game:GetService("RunService")
		
		-- ================================================
		-- STEP 1: KILL ALL SHADER CONNECTIONS FIRST
		-- ================================================
		pcall(function() Workspace.DescendantAdded:DisconnectAll() end)
		pcall(function() RunService.RenderStepped:DisconnectAll() end)
		pcall(function() getgenv().GI_SYSTEM = nil end)
		
		-- ================================================
		-- STEP 2: DISABLE + DESTROY EVERY EFFECT
		-- Disable first, then destroy — belt and suspenders
		-- ================================================
		for _, child in ipairs(Lighting:GetChildren()) do
		    pcall(function()
		        -- Disable before destroying so effect stops instantly
		        if child:FindFirstProperty("Enabled") then
		            child.Enabled = false
		        end
		        child:Destroy()
		    end)
		end
		
		-- Double-check — destroy anything that survived
		task.wait(0.05)
		for _, child in ipairs(Lighting:GetChildren()) do
		    pcall(function() child:Destroy() end)
		end
		
		-- ================================================
		-- STEP 3: RESTORE LIGHTING PROPERTIES
		-- ================================================
		local L = getgenv().ORIGINAL_LIGHTING
		
		if L and next(L) then
		    Lighting.Technology               = L.Technology
		    Lighting.Ambient                  = L.Ambient
		    Lighting.OutdoorAmbient           = L.OutdoorAmbient
		    Lighting.Brightness               = L.Brightness
		    Lighting.ColorShift_Bottom        = L.ColorShift_Bottom
		    Lighting.ColorShift_Top           = L.ColorShift_Top
		    Lighting.FogColor                 = L.FogColor
		    Lighting.FogEnd                   = L.FogEnd
		    Lighting.FogStart                 = L.FogStart
		    Lighting.GlobalShadows            = L.GlobalShadows
		    Lighting.ShadowSoftness           = L.ShadowSoftness
		    Lighting.EnvironmentDiffuseScale  = L.EnvironmentDiffuseScale
		    Lighting.EnvironmentSpecularScale = L.EnvironmentSpecularScale
		    Lighting.ExposureCompensation     = L.ExposureCompensation
		    Lighting.ClockTime                = L.ClockTime
		    Lighting.GeographicLatitude       = L.GeographicLatitude
		    print("[Reset] Lighting restored from snapshot.")
		else
		    Lighting.Technology               = Enum.Technology.Compatibility
		    Lighting.Ambient                  = Color3.fromRGB(127, 127, 127)
		    Lighting.OutdoorAmbient           = Color3.fromRGB(127, 127, 127)
		    Lighting.Brightness               = 2.0
		    Lighting.ColorShift_Bottom        = Color3.fromRGB(0, 0, 0)
		    Lighting.ColorShift_Top           = Color3.fromRGB(0, 0, 0)
		    Lighting.FogColor                 = Color3.fromRGB(191, 191, 191)
		    Lighting.FogEnd                   = 100000
		    Lighting.FogStart                 = 0
		    Lighting.GlobalShadows            = true
		    Lighting.ShadowSoftness           = 0.2
		    Lighting.EnvironmentDiffuseScale  = 1
		    Lighting.EnvironmentSpecularScale = 1
		    Lighting.ExposureCompensation     = 0
		    Lighting.ClockTime                = 14
		    Lighting.GeographicLatitude       = 41.733
		    print("[Reset] No snapshot — Roblox defaults applied.")
		end
		
		-- ================================================
		-- STEP 4: RESTORE SKY
		-- ================================================
		local skyData = getgenv().ORIGINAL_SKY
		if skyData then
		    local Sky = Instance.new("Sky")
		    Sky.SkyboxBk             = skyData.SkyboxBk
		    Sky.SkyboxDn             = skyData.SkyboxDn
		    Sky.SkyboxFt             = skyData.SkyboxFt
		    Sky.SkyboxLf             = skyData.SkyboxLf
		    Sky.SkyboxRt             = skyData.SkyboxRt
		    Sky.SkyboxUp             = skyData.SkyboxUp
		    Sky.CelestialBodiesShown = skyData.CelestialBodiesShown
		    Sky.StarCount            = skyData.StarCount
		    Sky.Parent = Lighting
		else
		    print("[Reset] No sky snapshot — leaving default procedural sky.")
		end
		
		-- ================================================
		-- STEP 5: RESTORE ATMOSPHERE
		-- ================================================
		local atmoData = getgenv().ORIGINAL_ATMO
		if atmoData then
		    local Atmo = Instance.new("Atmosphere")
		    Atmo.Density = atmoData.Density
		    Atmo.Offset  = atmoData.Offset
		    Atmo.Color   = atmoData.Color
		    Atmo.Decay   = atmoData.Decay
		    Atmo.Glare   = atmoData.Glare
		    Atmo.Haze    = atmoData.Haze
		    Atmo.Parent = Lighting
		    print("[Reset] Atmosphere restored from snapshot.")
		else
		    print("[Reset] No snapshot — leaving default lighting without Atmosphere.")
		end
		
		-- Explicit extra kill on bloom just in case anything re-added it
		task.wait(0.05)
		for _, child in ipairs(Lighting:GetChildren()) do
		    if child:IsA("BloomEffect") or child:IsA("ColorCorrectionEffect")
		    or child:IsA("SunRaysEffect") or child:IsA("DepthOfFieldEffect")
		    or child:IsA("BlurEffect") then
		        child.Enabled = false
		        child:Destroy()
		    end
		end
		
		-- ================================================
		-- STEP 6: RESTORE TERRAIN WATER + REMOVE CLOUDS
		-- ================================================
		local Terrain = Workspace:FindFirstChildOfClass("Terrain")
		if Terrain then
		    local W = getgenv().ORIGINAL_WATER
		    if W then
		        Terrain.WaterColor        = W.WaterColor
		        Terrain.WaterReflectance  = W.WaterReflectance
		        Terrain.WaterTransparency = W.WaterTransparency
		        Terrain.WaterWaveSize     = W.WaterWaveSize
		        Terrain.WaterWaveSpeed    = W.WaterWaveSpeed
		    else
		        Terrain.WaterColor        = Color3.fromRGB(16, 150, 203)
		        Terrain.WaterReflectance  = 1
		        Terrain.WaterTransparency = 0.3
		        Terrain.WaterWaveSize     = 0.15
		        Terrain.WaterWaveSpeed    = 10
		    end
		    for _, child in ipairs(Terrain:GetChildren()) do
		        if child:IsA("Clouds") then child:Destroy() end
		    end
		end
		
		-- ================================================
		-- STEP 7: RESTORE PART COLORS FROM SNAPSHOT
		-- ================================================
		local function isCharacterPart(part)
		    local model = part:FindFirstAncestorOfClass("Model")
		    return model and model:FindFirstChildOfClass("Humanoid") ~= nil
		end
		
		local snapshot = getgenv().ORIGINAL_COLORS
		local restored, skipped = 0, 0
		
		for _, obj in ipairs(Workspace:GetDescendants()) do
		    if obj:IsA("BasePart") and not isCharacterPart(obj) then
		        pcall(function()
		            if snapshot and snapshot[obj] then
		                obj.Color = snapshot[obj]
		                restored += 1
		            else
		                skipped += 1
		            end
		        end)
		    end
		end
		
		-- ================================================
		-- STEP 8: CLEAR ALL SNAPSHOT MEMORY
		-- ================================================
		getgenv().ORIGINAL_COLORS   = nil
		getgenv().ORIGINAL_LIGHTING = nil
		getgenv().ORIGINAL_WATER    = nil
		getgenv().ORIGINAL_SKY      = nil
		getgenv().ORIGINAL_ATMO     = nil
		
		print(string.format("[Reset] DONE. %d parts restored, %d skipped. Glow and fog removed.", restored, skipped))
	end,
	["space.lua"] = function()
		local Players   = game:GetService("Players")
		local Lighting  = game:GetService("Lighting")
		local Workspace = game:GetService("Workspace")
		
		-- Wipe any old snapshot first
		getgenv().ORIGINAL_COLORS   = setmetatable({}, {__mode = "k"})
		getgenv().ORIGINAL_LIGHTING = {}
		getgenv().ORIGINAL_WATER    = nil
		getgenv().ORIGINAL_SKY      = nil
		getgenv().ORIGINAL_ATMO     = nil
		
		local function isCharacterPart(part)
		    local model = part:FindFirstAncestorOfClass("Model")
		    return model and model:FindFirstChildOfClass("Humanoid") ~= nil
		end
		
		-- ------------------------------------------------
		-- Snapshot every BasePart color in the workspace
		-- ------------------------------------------------
		local colorCount = 0
		for _, obj in ipairs(Workspace:GetDescendants()) do
		    if obj:IsA("BasePart") and not isCharacterPart(obj) then
		        pcall(function()
		            getgenv().ORIGINAL_COLORS[obj] = obj.Color
		            colorCount += 1
		        end)
		    end
		end
		
		-- Also snapshot colors of parts that load in later
		Workspace.DescendantAdded:Connect(function(obj)
		    if obj:IsA("BasePart") and not isCharacterPart(obj) then
		        pcall(function()
		            if not getgenv().ORIGINAL_COLORS[obj] then
		                getgenv().ORIGINAL_COLORS[obj] = obj.Color
		            end
		        end)
		    end
		end)
		
		-- ------------------------------------------------
		-- Snapshot all Lighting properties
		-- ------------------------------------------------
		local L = getgenv().ORIGINAL_LIGHTING
		L.Technology               = Lighting.Technology
		L.Ambient                  = Lighting.Ambient
		L.OutdoorAmbient           = Lighting.OutdoorAmbient
		L.Brightness               = Lighting.Brightness
		L.ColorShift_Bottom        = Lighting.ColorShift_Bottom
		L.ColorShift_Top           = Lighting.ColorShift_Top
		L.FogColor                 = Lighting.FogColor
		L.FogEnd                   = Lighting.FogEnd
		L.FogStart                 = Lighting.FogStart
		L.GlobalShadows            = Lighting.GlobalShadows
		L.ShadowSoftness           = Lighting.ShadowSoftness
		L.EnvironmentDiffuseScale  = Lighting.EnvironmentDiffuseScale
		L.EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale
		L.ExposureCompensation     = Lighting.ExposureCompensation
		L.ClockTime                = Lighting.ClockTime
		L.GeographicLatitude       = Lighting.GeographicLatitude
		
		-- ------------------------------------------------
		-- Snapshot existing Sky if present
		-- ------------------------------------------------
		local existingSky = Lighting:FindFirstChildOfClass("Sky")
		if existingSky then
		    getgenv().ORIGINAL_SKY = {
		        SkyboxBk             = existingSky.SkyboxBk,
		        SkyboxDn             = existingSky.SkyboxDn,
		        SkyboxFt             = existingSky.SkyboxFt,
		        SkyboxLf             = existingSky.SkyboxLf,
		        SkyboxRt             = existingSky.SkyboxRt,
		        SkyboxUp             = existingSky.SkyboxUp,
		        CelestialBodiesShown = existingSky.CelestialBodiesShown,
		        StarCount            = existingSky.StarCount,
		    }
		end
		
		-- ------------------------------------------------
		-- Snapshot existing Atmosphere if present
		-- ------------------------------------------------
		local existingAtmo = Lighting:FindFirstChildOfClass("Atmosphere")
		if existingAtmo then
		    getgenv().ORIGINAL_ATMO = {
		        Density = existingAtmo.Density,
		        Offset  = existingAtmo.Offset,
		        Color   = existingAtmo.Color,
		        Decay   = existingAtmo.Decay,
		        Glare   = existingAtmo.Glare,
		        Haze    = existingAtmo.Haze,
		    }
		end
		
		-- ------------------------------------------------
		-- Snapshot Terrain water
		-- ------------------------------------------------
		local Terrain = Workspace:FindFirstChildOfClass("Terrain")
		if Terrain then
		    getgenv().ORIGINAL_WATER = {
		        WaterColor        = Terrain.WaterColor,
		        WaterReflectance  = Terrain.WaterReflectance,
		        WaterTransparency = Terrain.WaterTransparency,
		        WaterWaveSize     = Terrain.WaterWaveSize,
		        WaterWaveSpeed    = Terrain.WaterWaveSpeed,
		    }
		end
		
		print(string.format("[Snapshot] Ready. Saved %d part colors, lighting, sky, atmosphere & water. Safe to run shaders.", colorCount))
		
		local Players = game:GetService('Players')
		local Lighting = game:GetService('Lighting')
		local localPlayer = Players.LocalPlayer
		
		local function toGray(c)
		    local lum = 0.299 * c.R + 0.587 * c.G + 0.114 * c.B
		    return Color3.new(lum, lum, lum)
		end
		
		
		local function isAvatarPart(part)
		    for _, plr in ipairs(Players:GetPlayers()) do
		        local char = plr.Character
		        if char and part:IsDescendantOf(char) then
		            return true
		        end
		    end
		    return false
		end
		
		local grayCache = {}
		
		local function makeGray(part)
		    if not part:IsA('BasePart') then return end
		    if part.Name == "PandaTile" then return end
		    if grayCache[part] then return end
		    if isAvatarPart(part) then return end
		
		    grayCache[part] = true
		    part.Color = toGray(part.Color)
		end
		
		for _, obj in ipairs(workspace:GetDescendants()) do
		    pcall(makeGray, obj)
		end
		
		workspace.DescendantAdded:Connect(function(inst)
		    task.defer(function()
		        pcall(makeGray, inst)
		    end)
		end)
		
		
		local function protectAvatar(char)
		    if not char then return end
		
		    for _, part in ipairs(char:GetDescendants()) do
		        pcall(function()
		            if part:IsA('BasePart') and grayCache[part] then
		                grayCache[part] = nil
		            end
		        end)
		    end
		
		    char.DescendantAdded:Connect(function(inst)
		        task.defer(function()
		            pcall(function()
		                if inst:IsA('BasePart') then
		                    grayCache[inst] = nil
		                end
		            end)
		        end)
		    end)
		end
		
		for _, plr in ipairs(Players:GetPlayers()) do
		    protectAvatar(plr.Character)
		    plr.CharacterAdded:Connect(protectAvatar)
		end
		
		Players.PlayerAdded:Connect(function(plr)
		    protectAvatar(plr.Character)
		    plr.CharacterAdded:Connect(protectAvatar)
		end)
		
		
		Lighting:ClearAllChildren()
		
		local sky = Instance.new('Sky')
		sky.SkyboxBk = 'http://www.roblox.com/asset/?id=16262356578'
		sky.SkyboxDn = 'http://www.roblox.com/asset/?id=16262358026'
		sky.SkyboxFt = 'http://www.roblox.com/asset/?id=16262360469'
		sky.SkyboxLf = 'http://www.roblox.com/asset/?id=16262362003'
		sky.SkyboxRt = 'http://www.roblox.com/asset/?id=16262363873'
		sky.SkyboxUp = 'http://www.roblox.com/asset/?id=16262366016'
		sky.StarCount = 6000
		sky.Parent = Lighting
		
		local atmo = Instance.new('Atmosphere')
		atmo.Density = 0.7
		atmo.Offset = 0.1
		atmo.Color = Color3.fromRGB(130, 130, 130)
		atmo.Decay = Color3.fromRGB(40, 40, 40)
		atmo.Glare = 0
		atmo.Haze = 1
		atmo.Parent = Lighting
		
		Lighting.Ambient = Color3.fromRGB(90, 90, 90)
		Lighting.OutdoorAmbient = Color3.fromRGB(90, 90, 90)
		Lighting.ColorShift_Top = Color3.fromRGB(160, 160, 160)
		Lighting.ColorShift_Bottom = Color3.fromRGB(160, 160, 160)
		Lighting.FogColor = Color3.fromRGB(20, 20, 20)
		Lighting.FogEnd = 100000
		Lighting.Brightness = 2.0
		
		
		local bloom = Instance.new('BloomEffect')
		bloom.Enabled = true
		bloom.Intensity = 1.5
		bloom.Size = 64
		bloom.Threshold = 0.75
		bloom.Parent = Lighting
		
		local sunrays = Instance.new('SunRaysEffect')
		sunrays.Enabled = true
		sunrays.Intensity = 0.35
		sunrays.Spread = 1.0
		sunrays.Parent = Lighting
		
		local colorCorrection = Instance.new('ColorCorrectionEffect')
		colorCorrection.Saturation = 0
		colorCorrection.Brightness = 0.05
		colorCorrection.Contrast = 0.25
		colorCorrection.TintColor = Color3.fromRGB(255, 255, 255)
		colorCorrection.Enabled = true
		colorCorrection.Parent = Lighting
		
		-- LocalScript in StarterPlayerScripts
		
		local Workspace = game:GetService("Workspace")
		local Players = game:GetService("Players")
		
		local function isCharacterPart(part)
		    for _, player in ipairs(Players:GetPlayers()) do
		        if player.Character and part:IsDescendantOf(player.Character) then
		            return true
		        end
		    end
		    return false
		end
		
		local function applyLightGrey(part)
		    if part:IsA("BasePart") or part:IsA("Terrain") then
		        if isCharacterPart(part) then return end
		        if part.Name == "PandaTile" then return end
		
		        if part:IsA("Terrain") then
		            part.WaterColor = Color3.fromRGB(200, 200, 200)
		        else
		            local c = part.Color
		            local grey = 0.6 + (0.299 * c.R + 0.587 * c.G + 0.114 * c.B) * 0.4
		            part.Color = Color3.new(grey, grey, grey)
		        end
		    end
		end
		
		for _, obj in ipairs(Workspace:GetDescendants()) do
		    applyLightGrey(obj)
		end
		
		Workspace.DescendantAdded:Connect(applyLightGrey)
	end,
}

						function applyShade(url, juicebaker47)
							if true then return end -- shaders removed
							if L1.step4 < L1.step3 then
								task.spawn(function()
									pcall(fn16)
									if not url or url == "reset.lua" then
										if _EMBEDDED_SHADERS and _EMBEDDED_SHADERS["reset.lua"] then
											pcall(_EMBEDDED_SHADERS["reset.lua"])
										end
										SendNotification("mortal", "Shaders reset to default!", 2)
										return
									end

									local fileName = tostring(url):match("([^/]+)$") or tostring(url)
									local shaderFn = _EMBEDDED_SHADERS and (_EMBEDDED_SHADERS[fileName] or _EMBEDDED_SHADERS[url])
									local ok, result

									if shaderFn then
										ok, result = pcall(shaderFn)
									else
										ok, result = pcall(function()
											loadstring(game:HttpGet(url))()
										end)
									end

									if ok then
										SendNotification("mortal", juicebaker47 .. " shader applied!", 2)
									else
										SendNotification("mortal", "Failed to load shader: " .. tostring(result), 2)
									end
								end)

								return
							end
						end
					end
				end

				do
					function resetShades()
						applyShade(nil, "Reset")
					end
				end

				n16 = nil
