						createDropdown(_animEmotes, "Quick Reanim Emote", popularList, 4, function(chosen)
							if _G.__BUNDLED_Panda_API and _G.__BUNDLED_Panda_API.play_animation then
								local path = popularEmoteMap[chosen]
								if path then
									if _G.__BUNDLED_Panda_API.is_reanimated and not _G.__BUNDLED_Panda_API.is_reanimated() and _G.__BUNDLED_Panda_API.reanimate then
										_G.__BUNDLED_Panda_API.reanimate(true)
									end
									_G.__BUNDLED_Panda_API.play_animation(path, 1)
								end
							end
						end)

						createActionButton(_animEmotes, "Stop Reanim Emote", "Stops any playing reanimation animation track", 5, function()
							if _G.__BUNDLED_Panda_API and _G.__BUNDLED_Panda_API.stop_animation then
								_G.__BUNDLED_Panda_API.stop_animation()
							end
							return
						end)
					end
				end

