						local vcb2Title = Instance.new("TextLabel", vcb2Card)
						vcb2Title.Size = UDim2.new(1, -60, 0, 18)
						vcb2Title.Position = UDim2.new(0, 52, 0, 12)
						vcb2Title.Text = "Anti VCB 2 — Standalone Diagnostic Tool"
						vcb2Title.Font = Enum.Font.GothamBold
						vcb2Title.TextSize = 12
						vcb2Title.TextColor3 = tbl3.white
						vcb2Title.TextXAlignment = Enum.TextXAlignment.Left
						vcb2Title.BackgroundTransparency = 1
						local vcb2Sub = Instance.new("TextLabel", vcb2Card)
						vcb2Sub.Size = UDim2.new(1, -60, 0, 28)
						vcb2Sub.Position = UDim2.new(0, 52, 0, 32)
						vcb2Sub.Text = "Click below to open the dedicated floating Diagnostic Tool window."
						vcb2Sub.Font = Enum.Font.Gotham
						vcb2Sub.TextSize = 10
						vcb2Sub.TextColor3 = tbl3.textMuted
						vcb2Sub.TextXAlignment = Enum.TextXAlignment.Left
						vcb2Sub.TextWrapped = true
