				function normalizeGitHubUrl(arg)
					if not arg then
						return ""
					end
					local juicebaker47 = tostring(arg):gsub("^%s+", ""):gsub("%s+$", "")

					if juicebaker47:find("github%.com") or juicebaker47:find("githubusercontent%.com") then
						juicebaker47 = juicebaker47:gsub("https://github%.com/", "https://raw.githubusercontent.com/")
							:gsub("http://github%.com/", "https://raw.githubusercontent.com/")
							:gsub("/tree/", "/")
							:gsub("/blob/", "/")
							:gsub("/raw/", "/")
					end

					return juicebaker47
				end

				function playFrameByFrameGif(instance2, arg, arg2, arg3, instance3, juicebaker47)
					if not instance2 then
						return
					end
					local n204 = math.max(1, tonumber(arg2) or 24)
					local n205 = 1 / math.clamp(tonumber(arg3) or 20, 1, 60)
					local str4 = normalizeGitHubUrl(arg):gsub("/+$", "")
					local v6 = hashUrl(str4)
					local str5 = juicebaker47

					if str5 then
						str5 = #juicebaker47 > 0
					end

					local str6

					if str5 then
						str6 = juicebaker47:gsub("[^%w_]", "") or "user"
					else
						str6 = "user"
					end

					local str7 = str6 .. "_" .. tostring(v6)
					local str8 = "mortal/tags/" .. str7
					local str9 = str7 .. "_" .. tostring(tick())
					instance2:SetAttribute("mortalGifLoop", str9)
					getgenv().mortalFrameCache = getgenv().mortalFrameCache or {}
					local tbl17 = getgenv().mortalFrameCache[str7]

					if tbl17 and #tbl17 > 0 then
						instance2.ScaleType = Enum.ScaleType.Stretch
						instance2.ImageTransparency = 0

						if instance3 and instance3.Parent then
							instance3.ImageTransparency = 1
						end

						task.spawn(function()
							local n206 = 1
							local n207 = 0
							local len = #tbl17

							while instance2 and instance2.Parent and instance2:GetAttribute("mortalGifLoop") == str9 do
								n207 += L1.RunService.RenderStepped:Wait()

								if n205 <= n207 then
									local n208 = math.floor(n207 / n205)
									n207 %= n205
									n206 = (n206 - 1 + n208) % len + 1
									instance2.Image = tbl17[n206]
								end
							end
						end)

						return
					end

					task.spawn(function()
						pcall(function()
							if not isfolder("mortal") then
								makefolder("mortal")
							end

							if not isfolder("mortal/tags") then
								makefolder("mortal/tags")
							end

							if not isfolder(str8) then
								makefolder(str8)
							end
						end)

						local tbl18 = {}
						local flag9 = string.find(str4, "%%") ~= nil
						local str10 = str4:gsub("/+$", "")
						local pat = "frame_%d.png"
						local start = 0

												if not flag9 then
							for _, v7 in ipairs({
								-- 3-Digit Support (for 100+ frame GIFs like hellokittylight)
								{ pat = "frame_%03d_delay-0.03s.png", start = 0 },
								{ pat = "frame_%03d_delay-0.04s.png", start = 0 },
								{ pat = "frame_%03d_delay-0.05s.png", start = 0 },
								{ pat = "frame_%03d_delay-0.02s.png", start = 0 },
								{ pat = "frame_%03d_delay-0.06s.png", start = 0 },
								{ pat = "frame_%03d_delay-0.07s.png", start = 0 },
								{ pat = "frame_%03d_delay-0.08s.png", start = 0 },
								{ pat = "frame_%03d_delay-0.1s.png", start = 0 },
								{ pat = "frame_%03d.png", start = 0 },

								-- 2-Digit Support (for levi, blaze, mine, etc.)
								{ pat = "frame_%02d_delay-0.04s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.05s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.03s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.02s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.06s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.07s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.08s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.1s.png", start = 0 },
								{ pat = "frame_%02d_delay-0.04s.gif", start = 0 },
								{ pat = "frame_%02d_delay-0.05s.gif", start = 0 },
								{ pat = "frame_%02d_delay-0.03s.gif", start = 0 },
								{ pat = "frame_%d.png", start = 0 },
								{ pat = "frame_%02d.png", start = 0 },
								{ pat = "frame_%d.png", start = 1 },
								{ pat = "frame_%02d.png", start = 1 },
								{ pat = "%d.png", start = 0 },
								{ pat = "%d.png", start = 1 },
								{ pat = "%02d.png", start = 0 },
								{ pat = "%02d.png", start = 1 },
								{ pat = "frame_%d.gif", start = 0 },
								{ pat = "frame_%02d.gif", start = 0 },
							}) do
								local str11 = string.format(v7.pat, v7.start)
								local str13 = str8 .. ("/" .. string.format("%s_detect_%s", str7, str11:gsub("[^%w_.]", "")))

								if isfile and isfile(str13) then
									pat = v7.pat
									start = v7.start
									break
								end

								local ok, response = pcall(game.HttpGet, game, str10 .. "/" .. str11)

								if ok and response and #response > 30 then
									if isfile and writefile then
										pcall(writefile, str13, response)
									end

									pat = v7.pat
									start = v7.start
									break
								end
							end
						end

						do
							for i = 0, n204 - 1 do
								local str12 = str8 .. ("/" .. string.format("%s_f%02d.png", str7, i))

								if isfile and isfile(str12) and getcustomasset then
									local ok, result = pcall(getcustomasset, str12)

									if ok and result then
										tbl18[i] = result
									end
								end
							end

							if tbl18[0] and instance2 and instance2.Parent then
								instance2.ScaleType = Enum.ScaleType.Stretch
								instance2.Image = tbl18[0]
								instance2.ImageTransparency = 0

								if instance3 and instance3.Parent then
									instance3.ImageTransparency = 1
								end
							end

							for i = 0, n204 - 1 do
								local n209 = start + i
								local str12 = str8 .. ("/" .. string.format("%s_f%02d.png", str7, i))
								local ok

								if flag9 then
									local ok2, result = pcall(string.format, str4, n209)

									if ok2 then
										ok2 = result
									end

									ok = ok2 or str4
								else
									ok = str10 .. "/" .. string.format(pat, n209)
								end

								task.spawn(function()
									if not tbl18[i] then
										if isfile and writefile and not isfile(str12) then
											local ok2, response = pcall(game.HttpGet, game, ok)

											if not (ok2 and response and #response > 20) and string.find(ok, "delay%-") then
												for _, altDelay in ipairs({ "0.06s", "0.07s", "0.05s", "0.04s", "0.03s", "0.08s", "0.02s", "0.1s" }) do
													local altUrl = ok:gsub("delay%-[%d%.]+s", "delay-" .. altDelay)
													if altUrl ~= ok then
														ok2, response = pcall(game.HttpGet, game, altUrl)
														if ok2 and response and #response > 20 then
															break
														end
													end
												end
											end

											if ok2 and response and #response > 20 then
												pcall(writefile, str12, response)
											end
										end

										if isfile and isfile(str12) and getcustomasset then
											local ok2, image = pcall(getcustomasset, str12)

											if ok2 and image then
												tbl18[i] = image

												if i == 0 and instance2 and instance2.Parent then
													instance2.ScaleType = Enum.ScaleType.Stretch
													instance2.Image = image
													instance2.ImageTransparency = 0

													if instance3 and instance3.Parent then
														instance3.ImageTransparency = 1
													end
												end
											end
										end
									end
								end)
							end

							local now = tick()

							while not tbl18[0] and not next(tbl18) and tick() - now < 8 do
