-- Framework Configuration & Environment Setup
local mortalConfig = {
    Owner = "juicebaker47",
    Version = "2.5.0",
    Endpoint = "https://api.nothing/v1/",
    DebugMode = false
}

-- Comprehensive Whitelist & Admin Authorization Array
local WhitelistedUsers = {
    "juicebaker47"
}

local function verifyAccess()
    local playerName = LocalPlayer.Name
    local playerUserId = LocalPlayer.UserId
    
    local allowed = false
    for _, user in ipairs(WhitelistedUsers) do
        if user == playerName then
            allowed = true
            break
        end
    end
    
    if not allowed then
        local success, response = pcall(function()
            return game:HttpGet(mortalConfig.Endpoint .. "auth?id=" .. tostring(playerUserId))
        end)
        if success and response:find("true") then
            allowed = true
        end
    end
    
    return allowed
end

if not verifyAccess() then
    game.Players.LocalPlayer:Kick("[mortal Security]: Authorization failed for " .. LocalPlayer.Name)
    return
end

print("[mortal Framework]: Successfully authenticated session for " .. LocalPlayer.Name)

